export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  unit: string;
  image: string;
  description: string;
  rating: number;
  supplier: string;
  stock: number;
  tags: string[];
}

export interface CartItem extends Product {
  quantity: number;
}

export interface User {
  id: string;
  name: string;
  company: string;
  role: 'admin' | 'purchaser';
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  isThinking?: boolean;
}

import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
// Note: In a real production app, ensure API key is safe.
// Per instructions, we assume process.env.API_KEY is available.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateProcurementAdvice = async (
  query: string,
  contextData: string
): Promise<string> => {
  try {
    const model = 'gemini-2.5-flash-latest'; // Using Flash for speed in chat

    const systemInstruction = `
      You are an expert Enterprise Procurement Consultant named "ZhiCai AI".
      Your goal is to help procurement officers find products, compare specifications, and optimize their spending.

      Context about current available products:
      ${contextData}

      Rules:
      1. Be professional, concise, and helpful.
      2. If asked about products, recommend items from the provided context if possible.
      3. Suggest complementary items (e.g., if buying a printer, suggest paper).
      4. Use formatting like bullet points for clarity.
      5. If the user asks for something not in the context, give general procurement advice but mention it's not currently in stock.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: query,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text || "I'm sorry, I couldn't generate a response at the moment.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I apologize, but I am currently experiencing connection issues. Please try again later.";
  }
};

