import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateProcurementAdvice = async (
  query: string,
  contextData: string
): Promise<string> => {
  try {
    const model = 'gemini-2.5-flash-latest';

    const systemInstruction = `
      你是由“智采商城”开发的专业企业采购AI助手，名字叫“智采小助手”。
      你的目标是帮助企业采购人员寻找商品、对比参数、优化预算以及提供供应链建议。

      当前商城的商品上下文数据（部分）：
      ${contextData}

      回复规则：
      1. 请使用中文回复，语气专业、亲切、高效。
      2. 优先推荐上下文中的商品。
      3. 如果用户询问的商品不在上下文中，可以提供通用的采购建议（例如品牌推荐、选购要点），但要说明目前商城暂无库存。
      4. 回复格式尽量清晰，使用列表或分点陈述。
      5. 能够回答关于办公用品、电子设备、劳保用品等企业常见采购品类的问题。
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: query,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.7,
      }
    });

    return response.text || "抱歉，系统暂时无法生成回复。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "抱歉，网络连接异常，请稍后再试。";
  }
};

