import React, { useState, useRef, useEffect } from 'react';
import { Bot, X, Send, Sparkles, Loader2 } from 'lucide-react';
import { generateProcurementAdvice } from '../services/geminiService';
import { ChatMessage } from '../types';

interface AiAssistantProps {
  productContextData: string;
}

const AiAssistant: React.FC<AiAssistantProps> = ({ productContextData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: '您好！我是智采小助手。请问有什么可以帮您的？我可以帮您查找商品、对比参数或提供采购建议。' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: ChatMessage = { role: 'user', text: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    const responseText = await generateProcurementAdvice(input, productContextData);

    setMessages(prev => [...prev, { role: 'model', text: responseText }]);
    setIsLoading(false);
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <>
      {/* Floating Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`fixed bottom-8 right-8 z-50 p-4 rounded-full shadow-lg border-2 border-white transition-all duration-300 flex items-center gap-2 ${
          isOpen ? 'bg-slate-500 rotate-90 opacity-0 pointer-events-none' : 'bg-brand-600 hover:bg-brand-700 opacity-100'
        }`}
        title="智采AI助手"
      >
        <Sparkles className="text-white" />
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-8 right-8 z-50 w-[360px] max-w-[90vw] bg-white rounded-lg shadow-2xl border border-slate-200 flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right ${
          isOpen ? 'opacity-100 scale-100 translate-y-0 h-[550px]' : 'opacity-0 scale-90 translate-y-10 h-0 pointer-events-none'
        }`}
      >
        {/* Header */}
        <div className="bg-brand-600 p-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 p-1.5 rounded-lg backdrop-blur-sm">
              <Bot size={20} className="text-white" />
            </div>
            <div>
              <h3 className="text-white font-bold text-sm">智采智能采购助手</h3>
              <p className="text-brand-100 text-xs flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse"></span>
                Gemini 2.5 在线
              </p>
            </div>
          </div>
          <button onClick={() => setIsOpen(false)} className="text-white/80 hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 bg-[#f5f5f5] space-y-4">
          {messages.map((msg, idx) => (
            <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div 
                className={`max-w-[85%] rounded-lg px-4 py-2.5 text-sm leading-relaxed ${
                  msg.role === 'user' 
                    ? 'bg-brand-600 text-white' 
                    : 'bg-white text-[#333] border border-[#eee] shadow-sm'
                }`}
              >
                {msg.text.split('\n').map((line, i) => (
                  <p key={i} className={`min-h-[1em] ${line.trim().startsWith('-') || line.trim().match(/^\d+\./) ? 'pl-2' : ''}`}>
                    {line}
                  </p>
                ))}
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-white border border-[#eee] rounded-lg px-4 py-3 shadow-sm">
                <div className="flex items-center gap-2 text-[#999] text-xs">
                  <Loader2 size={14} className="animate-spin" />
                  正在思考中...
                </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-3 bg-white border-t border-[#eee]">
          <div className="relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="请输入您的问题，例如：推荐一款高性价比的人体工学椅..."
              className="w-full bg-[#f8f8f8] border border-transparent hover:bg-white hover:border-[#ddd] focus:bg-white focus:border-brand-500 rounded-md pl-3 pr-10 py-2 text-sm focus:outline-none resize-none h-10 transition-all"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !input.trim()}
              className="absolute right-1 top-1 p-1.5 text-brand-600 hover:bg-brand-50 rounded disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default AiAssistant;

