import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { MOCK_PRODUCTS, CATEGORIES } from '../services/mockData';
import ProductCard from '../components/ProductCard';
import { ChevronRight } from 'lucide-react';

interface MarketplaceProps {
  addToCart: (product: Product) => void;
}

const Marketplace: React.FC<MarketplaceProps> = ({ addToCart }) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('全部');
  const [priceSort, setPriceSort] = useState<'asc' | 'desc' | null>(null);

  const filteredProducts = useMemo(() => {
    let prods = MOCK_PRODUCTS;
    if (selectedCategory !== '全部') {
      prods = prods.filter(p => p.category === selectedCategory);
    }
    if (priceSort === 'asc') {
      prods = [...prods].sort((a, b) => a.price - b.price);
    } else if (priceSort === 'desc') {
      prods = [...prods].sort((a, b) => b.price - a.price);
    }
    return prods;
  }, [selectedCategory, priceSort]);

  return (
    <div className="bg-[#f4f4f4] min-h-screen py-4 font-sans">
      <div className="max-w-[1200px] mx-auto px-4">

        {/* Breadcrumb */}
        <div className="flex items-center text-xs text-[#666] mb-4">
          <span>首页</span>
          <ChevronRight size={12} className="mx-1" />
          <span>全部商品</span>
          {selectedCategory !== '全部' && (
            <>
              <ChevronRight size={12} className="mx-1" />
              <span>{selectedCategory}</span>
            </>
          )}
        </div>

        <div className="flex gap-4">
          {/* Sidebar */}
          <div className="w-[200px] flex-shrink-0 bg-white border border-[#eee] p-4 hidden md:block">
            <h3 className="font-bold text-[#333] mb-4 text-sm">商品分类</h3>
            <ul className="space-y-2">
              <li 
                className={`text-sm cursor-pointer hover:text-brand-600 ${selectedCategory === '全部' ? 'text-brand-600 font-bold' : 'text-[#666]'}`}
                onClick={() => setSelectedCategory('全部')}
              >
                全部商品
              </li>
              {CATEGORIES.map(cat => (
                <li 
                  key={cat} 
                  className={`text-sm cursor-pointer hover:text-brand-600 ${selectedCategory === cat ? 'text-brand-600 font-bold' : 'text-[#666]'}`}
                  onClick={() => setSelectedCategory(cat)}
                >
                  {cat}
                </li>
              ))}
            </ul>
          </div>

          {/* Main List */}
          <div className="flex-1">
            {/* Filter Bar */}
            <div className="bg-white border border-[#eee] p-2 mb-4 flex items-center gap-4 text-sm">
              <button 
                className={`px-4 py-1 border ${!priceSort ? 'border-brand-600 text-brand-600 bg-brand-50' : 'border-[#ddd] text-[#333] hover:border-brand-600'}`}
                onClick={() => setPriceSort(null)}
              >
                综合排序
              </button>
              <button 
                className={`px-4 py-1 border ${priceSort === 'asc' ? 'border-brand-600 text-brand-600 bg-brand-50' : 'border-[#ddd] text-[#333] hover:border-brand-600'}`}
                onClick={() => setPriceSort('asc')}
              >
                价格 ↑
              </button>
              <button 
                className={`px-4 py-1 border ${priceSort === 'desc' ? 'border-brand-600 text-brand-600 bg-brand-50' : 'border-[#ddd] text-[#333] hover:border-brand-600'}`}
                onClick={() => setPriceSort('desc')}
              >
                价格 ↓
              </button>
              <div className="ml-auto text-[#999] text-xs">
                共 <span className="text-brand-600">{filteredProducts.length}</span> 件商品
              </div>
            </div>

            {/* Product Grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              {filteredProducts.map(product => (
                <div key={product.id} className="h-[320px]">
                   <ProductCard product={product} onAddToCart={addToCart} />
                </div>
              ))}
            </div>

            {filteredProducts.length === 0 && (
              <div className="bg-white p-12 text-center text-[#999]">
                暂无相关商品
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Marketplace;

