  const FlowDesigner = () => {
    // Simplified Mock Flow Structure
    const [nodes, setNodes] = useState<FlowNode[]>([
      { id: 'start', type: 'start', title: '发起人', content: '全员可发起' },
      { id: 'appr-1', type: 'approver', title: '部门经理', content: '指定角色: 部门经理' },
      { id: 'appr-2', type: 'approver', title: '财务总监', content: '指定人员: 王总' },
      { id: 'end', type: 'end', title: '流程结束' }
    ]);

    const addNode = (index: number, type: 'approver' | 'condition') => {
      const newNode: FlowNode = {
        id: Date.now().toString(),
        type: type,
        title: type === 'approver' ? '新审批人' : '条件分支',
        content: type === 'approver' ? '请选择' : '设置条件'
      };
      const newNodes = [...nodes];
      newNodes.splice(index + 1, 0, newNode);
      setNodes(newNodes);
    };

    const deleteNode = (index: number) => {
      const newNodes = [...nodes];
      newNodes.splice(index, 1);
      setNodes(newNodes);
    };

    return (
      <div className="h-[calc(100vh-200px)] bg-slate-100 rounded-3xl overflow-y-auto p-10 relative">
         <div className="flex flex-col items-center gap-4">
            {nodes.map((node, index) => (
               <React.Fragment key={node.id}>
                  {/* Node Card */}
                  <div className="relative group">
                     <div className={`w-64 p-4 rounded-2xl shadow-sm border-2 transition-all cursor-pointer hover:shadow-md ${
                        node.type === 'start' ? 'bg-white border-blue-200' :
                        node.type === 'end' ? 'bg-slate-50 border-slate-200' :
                        node.type === 'condition' ? 'bg-white border-amber-200' :
                        'bg-white border-blue-200 hover:border-blue-400'
                     }`}>
                        <div className={`flex items-center gap-2 mb-2 pb-2 border-b ${
                           node.type === 'start' ? 'border-blue-50 text-blue-600' :
                           node.type === 'end' ? 'border-slate-100 text-slate-400' :
                           node.type === 'condition' ? 'border-amber-50 text-amber-600' :
                           'border-blue-50 text-blue-600'
                        }`}>
                           {node.type === 'start' && <PlayCircle size={16} />}
                           {node.type === 'end' && <StopCircle size={16} />}
                           {node.type === 'approver' && <User size={16} />}
                           {node.type === 'condition' && <GitBranch size={16} />}
                           <span className="text-xs font-bold uppercase">{node.title}</span>

                           {node.type !== 'start' && node.type !== 'end' && (
                              <button 
                                onClick={(e) => { e.stopPropagation(); deleteNode(index); }}
                                className="ml-auto text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                              >
                                 <XCircle size={14} />
                              </button>
                           )}
                        </div>
                        <div className="flex justify-between items-center">
                           <span className="text-sm font-medium text-slate-700">{node.content || '请设置'}</span>
                           <ChevronRight size={14} className="text-slate-300" />
                        </div>
                     </div>
                  </div>

                  {/* Connector Line & Add Button (Except after End) */}
                  {node.type !== 'end' && (
                     <div className="flex flex-col items-center">
                        <div className="h-6 w-0.5 bg-slate-300"></div>
                        <div className="relative group z-10">
                           <button className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center shadow-md hover:scale-110 transition-transform">
                              <Plus size={14} />
