                           <div className="absolute left-1/2 top-8 -translate-x-1/2 bg-white shadow-xl rounded-xl p-2 hidden group-hover:flex gap-2 border border-slate-100 w-max">
                              <button 
                                onClick={() => addNode(index, 'approver')}
                                className="flex items-center gap-2 px-3 py-1.5 hover:bg-slate-50 rounded-lg text-xs font-bold text-slate-700"
                              >
                                 <User size={14} className="text-blue-500"/> 审批人
                              </button>
                              <button 
                                onClick={() => addNode(index, 'condition')}
                                className="flex items-center gap-2 px-3 py-1.5 hover:bg-slate-50 rounded-lg text-xs font-bold text-slate-700"
                              >
                                 <GitBranch size={14} className="text-amber-500"/> 条件分支
                              </button>
                           </div>
                        </div>
                        <div className="h-6 w-0.5 bg-slate-300"></div>
                     </div>
                  )}
               </React.Fragment>
            ))}
         </div>
      </div>
    );
  };

