        n.type === 'approver' ? 'bg-orange-50 border-orange-100' :
        n.type === 'notifier' ? 'bg-blue-50 border-blue-100' :
        n.type === 'condition' ? 'bg-white border-slate-200' :
        'bg-slate-50 border-slate-200';

      const titleColor = 
        n.type === 'start' ? 'text-indigo-700' :
        n.type === 'approver' ? 'text-orange-700' :
        n.type === 'notifier' ? 'text-blue-700' :
        'text-slate-700';

      if (n.type === 'end') {
         return (
            <div className="flex flex-col items-center">
               <div className="w-3 h-3 rounded-full bg-slate-300 mb-2"></div>
               <div className="px-4 py-1.5 bg-slate-100 rounded-full text-xs font-bold text-slate-500">流程结束</div>
            </div>
         );
      }

      return (
        <div className="relative group z-10">
           <div 
             onClick={() => setActiveNodeId(n.id)}
