                      </div>
                   ))}
                </div>
             </div>

             {/* Merge Point */}
             <AddButton />
             <NodeRenderer node={node.childNode || null} />
          </div>
       );
    }

    return (
       <div className="flex flex-col items-center">
          <NodeCard n={node} />
