    const isRoute = node.type === 'route';
    const isEnd = node.type === 'end';

    // Node Card Component
    const NodeCard = ({ n }: { n: FlowNode }) => {
      const bgColor = 
        n.type === 'start' ? 'bg-indigo-50 border-indigo-100' :
        n.type === 'approver' ? 'bg-orange-50 border-orange-100' :
        n.type === 'notifier' ? 'bg-blue-50 border-blue-100' :
        n.type === 'condition' ? 'bg-white border-slate-200' :
        'bg-slate-50 border-slate-200';

      const titleColor = 
        n.type === 'start' ? 'text-indigo-700' :
        n.type === 'approver' ? 'text-orange-700' :
        n.type === 'notifier' ? 'text-blue-700' :
        'text-slate-700';

      if (n.type === 'end') {
         return (
            <div className="flex flex-col items-center">
               <div className="w-3 h-3 rounded-full bg-slate-300 mb-2"></div>
               <div className="px-4 py-1.5 bg-slate-100 rounded-full text-xs font-bold text-slate-500">流程结束</div>
            </div>
         );
      }

      return (
        <div className="relative group z-10">
           <div 
             onClick={() => setActiveNodeId(n.id)}
             className={`w-[220px] rounded-xl border-2 shadow-sm cursor-pointer transition-all hover:shadow-md hover:scale-105 ${bgColor} ${activeNodeId === n.id ? 'ring-2 ring-offset-2 ring-blue-500' : ''}`}
           >
              <div className={`px-4 py-2 border-b text-xs font-bold flex justify-between items-center ${titleColor} ${n.type === 'condition' ? 'border-slate-100' : 'border-black/5'}`}>
                 <span>{n.name}</span>
                 {n.type !== 'start' && <button className="opacity-0 group-hover:opacity-100 hover:text-red-500"><X size={14}/></button>}
              </div>
              <div className="px-4 py-3 flex justify-between items-center">
                 <span className="text-sm font-medium text-slate-700 truncate">{n.content || '请设置'}</span>
                 <ChevronRight size={14} className="text-slate-300" />
              </div>
           </div>
        </div>
      );
    };

    // Add Button Component
    const AddButton = () => (
       <div className="w-full h-20 flex items-center justify-center relative group z-0">
          <div className="absolute top-0 bottom-0 w-0.5 bg-slate-300"></div>
          <button className="relative z-10 w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-lg hover:scale-110 transition-transform">
             <Plus size={18} />
          </button>
          {/* Popover for Add - Simplified as hidden for now */}
       </div>
    );

    if (isRoute && node.conditionNodes) {
       return (
          <div className="flex flex-col items-center">
             <div className="relative flex justify-center py-8">
                <div className="absolute top-0 w-0.5 h-8 bg-slate-300"></div>
                <div className="absolute bottom-0 w-0.5 h-8 bg-slate-300"></div>
                <button className="absolute top-8 z-10 px-4 py-1.5 bg-white border border-slate-200 rounded-full text-xs font-bold text-slate-500 shadow-sm hover:text-blue-600 hover:border-blue-200">
                   添加条件
                </button>

                {/* Branch Container */}
                <div className="flex gap-8 px-4 bg-slate-50/50 rounded-3xl border border-dashed border-slate-200 pt-8 pb-4 relative">
                   {/* Horizontal connector line logic is complex in CSS, simplified here */}
                   {node.conditionNodes.map((branch, idx) => (
                      <div key={branch.id} className="flex flex-col items-center relative">
                         {/* Branch Content */}
                         <NodeCard n={branch} />
                         <AddButton />
                         {branch.childNode ? <NodeRenderer node={branch.childNode} parentNode={branch} /> : null}
                         {/* End of branch logic connector */}
                         {!branch.childNode && <div className="h-full w-0.5 bg-slate-300 opacity-20"></div>} 
                      </div>
                   ))}
                </div>
             </div>

             {/* Merge Point */}
             <AddButton />
             <NodeRenderer node={node.childNode || null} />
          </div>
       );
    }

    return (
       <div className="flex flex-col items-center">
          <NodeCard n={node} />
          {!isEnd && (
             <>
                <AddButton />
                <NodeRenderer node={node.childNode || null} />
