                    activeFieldId === field.id ? 'border-blue-500 shadow-md ring-4 ring-blue-500/10' : 'border-transparent hover:border-blue-200'
                  }`}
                >
                   <div className="flex justify-between items-center mb-2">
                      <label className="text-sm font-bold text-slate-700">
                        {field.label} {field.required && <span className="text-red-500">*</span>}
                      </label>
                      {activeFieldId === field.id && (
                        <div className="absolute right-2 top-2 flex gap-1">
                           <button className="p-1 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded"><Copy size={12} /></button>
                           <button onClick={(e) => {e.stopPropagation(); removeFormField(field.id)}} className="p-1 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded"><Trash2 size={12} /></button>
                        </div>
                      )}
                   </div>

                   {/* Field Renderers */}
                   {['input', 'number', 'money'].includes(field.type) && (
                      <div className="text-sm text-slate-400">{field.placeholder}</div>
                   )}
                   {field.type === 'textarea' && (
                      <div className="h-16 bg-slate-50 rounded-lg p-2 text-sm text-slate-400">{field.placeholder}</div>
