              <div className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold text-sm text-center">提交申请</div>
           </div>
        </div>
      </div>

      {/* 3. Property Config Panel */}
      <div className="w-80 bg-white border-l border-slate-200 flex flex-col animate-in slide-in-from-right duration-200">
        <div className="p-4 border-b border-slate-100">
          <h3 className="font-bold text-slate-900">字段属性</h3>
        </div>
        {activeField ? (
          <div className="p-5 space-y-6 overflow-y-auto flex-1">
             <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase">标题</label>
                <input 
                  type="text" 
                  value={activeField.label}
                  onChange={(e) => updateFormField(activeField.id, { label: e.target.value })}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                />
             </div>
             <div className="space-y-2">
                <label className="text-xs font-bold text-slate-500 uppercase">提示文字</label>
                <input 
                  type="text" 
                  value={activeField.placeholder}
                  onChange={(e) => updateFormField(activeField.id, { placeholder: e.target.value })}
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                />
             </div>

             {/* Options Editor for Select */}
             {activeField.options && (
               <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase">选项配置</label>
                  <div className="space-y-2">
                     {activeField.options.map((opt, idx) => (
                       <div key={idx} className="flex gap-2">
                          <input 
                            type="text" 
                            value={opt}
                            onChange={(e) => {
                               const newOpts = [...(activeField.options || [])];
                               newOpts[idx] = e.target.value;
                               updateFormField(activeField.id, { options: newOpts });
                            }}
                            className="flex-1 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                          />
                          <button 
                            onClick={() => {
                               const newOpts = activeField.options?.filter((_, i) => i !== idx);
                               updateFormField(activeField.id, { options: newOpts });
                            }}
                            className="text-slate-400 hover:text-red-500"
                          >
                             <X size={16} />
                          </button>
                       </div>
                     ))}
                     <button 
                        onClick={() => updateFormField(activeField.id, { options: [...(activeField.options || []), `选项${(activeField.options?.length || 0) + 1}`] })}
                        className="text-xs font-bold text-blue-600 hover:underline flex items-center gap-1"
                     >
                        <Plus size={12} /> 添加选项
                     </button>
                  </div>
               </div>
             )}

             <div className="pt-6 border-t border-slate-100">
                <label className="flex items-center justify-between cursor-pointer group">
                   <span className="text-sm font-medium text-slate-700">必填项</span>
                   <div className="relative">
                      <input 
                        type="checkbox" 
                        className="sr-only peer"
                        checked={activeField.required}
                        onChange={(e) => updateFormField(activeField.id, { required: e.target.checked })}
                      />
                      <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                   </div>
                </label>
             </div>
          </div>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
             <Layout size={48} className="mb-4 opacity-20" />
             <p className="text-sm">请选择左侧字段进行配置</p>
          </div>
