                 </div>

                 <div>
                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">审批人类型</label>
                    <div className="grid grid-cols-2 gap-3">
                       {['指定成员', '部门主管', '角色', '发起人自选'].map(t => (
                          <div key={t} className="border border-slate-200 rounded-lg p-3 text-center text-sm font-medium hover:border-blue-500 hover:text-blue-600 cursor-pointer bg-slate-50 hover:bg-blue-50 transition-all">
                             {t}
                          </div>
                       ))}
                    </div>
                 </div>

                 <div className="pt-6 border-t border-slate-100">
                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">多人审批方式</label>
                    <div className="space-y-2">
