    const toggleMatCat = (id: string, nodes: MaterialCategory[]): MaterialCategory[] => {
      return nodes.map(node => {
        if (node.id === id) return { ...node, expanded: !node.expanded };
        if (node.children) return { ...node, children: toggleMatCat(id, node.children) };
        return node;
      });
    };

    const handleToggleMatCat = (id: string) => {
      setMatCategories(toggleMatCat(id, matCategories));
    };

    const renderMatTree = (nodes: MaterialCategory[], depth = 0) => {
      return nodes.map(node => (
        <div key={node.id}>
          <div 
            onClick={() => setSelectedMatCatId(node.id)}
            className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-colors group ${selectedMatCatId === node.id ? 'bg-blue-50 text-blue-700' : 'hover:bg-slate-50 text-slate-700'}`}
            style={{ paddingLeft: `${depth * 16 + 12}px` }}
          >
            <div className="flex items-center gap-2 overflow-hidden">
              {node.children && node.children.length > 0 ? (
                <button 
                  onClick={(e) => { e.stopPropagation(); handleToggleMatCat(node.id); }}
                  className="p-0.5 rounded hover:bg-black/5 text-slate-400"
                >
                  {node.expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                </button>
              ) : (
                <span className="w-4"></span>
