            </div>
            <span className="text-[10px] text-slate-400 bg-slate-100 px-1.5 rounded">{node.count}</span>
          </div>
          {node.expanded && node.children && (
            <div>{renderMatTree(node.children, depth + 1)}</div>
          )}
        </div>
      ));
    };

    // Find current category name
    const findCatName = (nodes: MaterialCategory[], id: string): string => {
      for (const node of nodes) {
        if (node.id === id) return node.name;
        if (node.children) {
          const found = findCatName(node.children, id);
          if (found) return found;
        }
      }
      return '';
    };
    const currentCatName = findCatName(matCategories, selectedMatCatId);

    // Filter materials based on search
