// --- Types for Workflow & Form ---

type FormFieldType = 'input' | 'textarea' | 'number' | 'money' | 'date' | 'date_range' | 'select' | 'multi_select' | 'upload' | 'dept_user';

interface FormField {
  id: string;
  type: FormFieldType;
  label: string;
  required: boolean;
  placeholder?: string;
  options?: string[]; // For select/radio
  props?: any;
}

type FlowNodeType = 'start' | 'approver' | 'notifier' | 'route' | 'condition' | 'end';

interface FlowNode {
  id: string;
  type: FlowNodeType;
  name?: string;
  content?: string;
  props?: any;
  childNode?: FlowNode | null;
  conditionNodes?: FlowNode[]; // For route nodes
}

interface WorkflowDef {
  id: string;
  name: string;
  group: string;
  description: string;
  icon: any;
  status: 'active' | 'draft';
  updatedAt: string;
  formFields: FormField[];
  flowData: FlowNode;
}

// --- Types for Organization ---
interface DeptNode {
  id: string;
  name: string;
  count?: number;
  expanded?: boolean;
  children?: DeptNode[];
}

interface Member {
  id: string;
  name: string;
  avatar?: string;
  role: string;
  jobNo: string;
  phone: string;
  email: string;
  status: 'active' | 'inactive';
}

// --- Types for Permission ---
interface Role {
  id: string;
  name: string;
  description: string;
  isSystem: boolean;
  memberCount: number;
}

// --- Types for Material ---
interface MaterialCategory {
  id: string;
  name: string;
  count: number;
  expanded?: boolean;
  children?: MaterialCategory[];
