          {/* Center Control based on Mode */}
          <div className="flex-1 flex justify-center">
            {editorMode === 'create' ? (
              // Wizard Steps
              <div className="flex items-center gap-4">
                <div className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-bold transition-colors ${createStep === 1 ? 'bg-blue-600 text-white' : 'bg-blue-50 text-blue-600'}`}>
                  <div className="w-5 h-5 rounded-full bg-white/20 flex items-center justify-center text-xs">1</div>
                  表单设计
                </div>
                <div className="w-8 h-0.5 bg-slate-200"></div>
                <div className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-bold transition-colors ${createStep === 2 ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                  <div className="w-5 h-5 rounded-full bg-white/20 flex items-center justify-center text-xs">2</div>
                  流程设计
                </div>
              </div>
            ) : (
              // Edit Tabs
              <div className="flex bg-slate-100 p-1 rounded-xl">
                <button 
                  onClick={() => setEditorTab('forms')}
                  className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${editorTab === 'forms' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-900'}`}
                >
                  <LayoutList size={16} className="inline mr-2" /> 表单设计
                </button>
                <button 
                  onClick={() => setEditorTab('flows')}
                  className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${editorTab === 'flows' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-900'}`}
