  const renderWorkflowView = () => {
    return workflowView === 'list' ? renderWorkflowList() : renderWorkflowEditor();
  };

  const renderMaterialManagement = () => {
    // Helper to find category name
    const findCatName = (nodes: MaterialCategory[], id: string): string => {
        for (const node of nodes) {
            if (node.id === id) return node.name;
            if (node.children) {
                const found = findCatName(node.children, id);
                if (found) return found;
            }
        }
        return '';
    };
    const currentCatName = findCatName(matCategories, selectedMatCatId);

    const toggleCat = (id: string, nodes: MaterialCategory[]): MaterialCategory[] => {
      return nodes.map(node => {
        if (node.id === id) return { ...node, expanded: !node.expanded };
        if (node.children) return { ...node, children: toggleCat(id, node.children) };
        return node;
      });
    };

    const handleCatToggle = (id: string) => {
        setMatCategories(toggleCat(id, matCategories));
    }

    const renderCatTree = (nodes: MaterialCategory[], depth = 0) => {
      return nodes.map(node => (
        <div key={node.id}>
          <div 
            onClick={() => setSelectedMatCatId(node.id)}
            className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-colors group ${selectedMatCatId === node.id ? 'bg-blue-50 text-blue-700' : 'hover:bg-slate-50 text-slate-700'}`}
            style={{ paddingLeft: `${depth * 16 + 12}px` }}
          >
            <div className="flex items-center gap-2 overflow-hidden">
              {node.children && node.children.length > 0 ? (
                <button 
                  onClick={(e) => { e.stopPropagation(); handleCatToggle(node.id); }}
                  className="p-0.5 rounded hover:bg-black/5 text-slate-400"
                >
                  {node.expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                </button>
              ) : (
                <span className="w-4"></span>
              )}
              <Package size={16} className={`shrink-0 ${selectedMatCatId === node.id ? 'text-blue-600' : 'text-slate-400'}`} />
              <span className="text-sm font-medium truncate">{node.name}</span>
            </div>
            <div className="flex items-center opacity-0 group-hover:opacity-100 transition-opacity">
               <button title="添加子分类" className="p-1 hover:text-blue-600 text-slate-400"><Plus size={14}/></button>
            </div>
          </div>
          {node.expanded && node.children && (
            <div>{renderCatTree(node.children, depth + 1)}</div>
          )}
        </div>
      ));
    };

    return (
      <div className="flex h-[calc(100vh-140px)] gap-6 animate-in fade-in duration-300">
        {/* Left: Category Tree */}
