                 </h3>
                 <div className="border-2 border-dashed border-slate-200 rounded-2xl p-8 flex flex-col items-center justify-center text-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group">
                    <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-2 group-hover:bg-blue-100 transition-colors">
                       <Plus size={24} className="text-slate-400 group-hover:text-blue-600" />
                    </div>
                    <span className="text-xs font-bold text-slate-500 group-hover:text-blue-600">点击上传图片</span>
                 </div>
              </div>
           </div>
        </div>

        <div className="fixed bottom-0 left-64 right-0 p-4 bg-white border-t border-slate-200 flex justify-center gap-4 z-10">
           <button 
             onClick={() => setIsCreatingMaterial(false)}
             className="px-8 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200 transition-colors"
           >
             取消
           </button>
           <button 
             onClick={handleCreateMaterial}
             className="px-8 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-colors flex items-center gap-2"
           >
             <Save size={18} /> 保存物料
           </button>
        </div>
      </div>
    );
  };

  const renderMaterialManagement = () => {
    // If in creation mode, render the form
    if (isCreatingMaterial) {
      return renderCreateMaterialForm();
    }

    const toggleMatCat = (id: string, nodes: MaterialCategory[]): MaterialCategory[] => {
      return nodes.map(node => {
        if (node.id === id) return { ...node, expanded: !node.expanded };
        if (node.children) return { ...node, children: toggleMatCat(id, node.children) };
        return node;
      });
    };

    const handleToggleMatCat = (id: string) => {
      setMatCategories(toggleMatCat(id, matCategories));
    };

    const renderMatTree = (nodes: MaterialCategory[], depth = 0) => {
      return nodes.map(node => (
        <div key={node.id}>
          <div 
            onClick={() => setSelectedMatCatId(node.id)}
            className={`flex items-center justify-between px-3 py-2 rounded-lg cursor-pointer transition-colors group ${selectedMatCatId === node.id ? 'bg-blue-50 text-blue-700' : 'hover:bg-slate-50 text-slate-700'}`}
            style={{ paddingLeft: `${depth * 16 + 12}px` }}
          >
            <div className="flex items-center gap-2 overflow-hidden">
              {node.children && node.children.length > 0 ? (
                <button 
                  onClick={(e) => { e.stopPropagation(); handleToggleMatCat(node.id); }}
                  className="p-0.5 rounded hover:bg-black/5 text-slate-400"
                >
                  {node.expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                </button>
              ) : (
                <span className="w-4"></span>
              )}
              <Package size={16} className={`shrink-0 ${selectedMatCatId === node.id ? 'text-blue-600' : 'text-slate-400'}`} />
              <span className="text-sm font-medium truncate">{node.name}</span>
            </div>
            <span className="text-[10px] text-slate-400 bg-slate-100 px-1.5 rounded">{node.count}</span>
          </div>
          {node.expanded && node.children && (
            <div>{renderMatTree(node.children, depth + 1)}</div>
          )}
        </div>
      ));
    };

    // Find current category name
    const findCatName = (nodes: MaterialCategory[], id: string): string => {
      for (const node of nodes) {
        if (node.id === id) return node.name;
        if (node.children) {
          const found = findCatName(node.children, id);
          if (found) return found;
        }
      }
      return '';
    };
    const currentCatName = findCatName(matCategories, selectedMatCatId);

    // Filter materials based on search
    const filteredMaterials = materials.filter(m => 
      m.name.includes(materialSearch) || m.code.includes(materialSearch) || m.spec.includes(materialSearch)
    );

    return (
      <div className="flex h-[calc(100vh-140px)] gap-6 animate-in fade-in duration-300">
        {/* Left: Material Category Tree */}
        <div className="w-72 bg-white rounded-3xl border border-slate-200 flex flex-col shadow-sm">
           <div className="p-5 border-b border-slate-100 flex justify-between items-center">
              <h3 className="font-bold text-slate-900 flex items-center gap-2">
                 <Boxes size={18} className="text-blue-600" /> 物料分类
              </h3>
              <button className="p-1.5 hover:bg-slate-100 rounded-lg text-slate-500 transition-colors">
                 <Plus size={18} />
              </button>
           </div>
           <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
              {renderMatTree(matCategories)}
           </div>
        </div>

        {/* Right: Material List */}
        <div className="flex-1 bg-white rounded-3xl border border-slate-200 flex flex-col shadow-sm overflow-hidden">
           {/* Toolbar */}
           <div className="p-6 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                 <h2 className="text-xl font-black text-slate-900 flex items-center gap-2">
                    {currentCatName || '全部物料'} 
                    <span className="text-sm font-medium text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">
                       {filteredMaterials.length} 条
                    </span>
                 </h2>
                 <p className="text-xs text-slate-500 mt-1">物料主数据管理中心</p>
              </div>
              <div className="flex gap-3">
                 <div className="relative">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="搜索物料编码、名称或规格..." 
                      value={materialSearch}
                      onChange={(e) => setMaterialSearch(e.target.value)}
                      className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 w-64" 
                    />
                 </div>
                 <button className="flex items-center gap-2 px-4 py-2.5 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50 transition-all">
                    <UploadCloud size={16} /> 导入
                 </button>
                 <button 
                   onClick={() => setIsCreatingMaterial(true)}
                   className="flex items-center gap-2 px-4 py-2.5 bg-slate-900 text-white rounded-xl text-sm font-bold hover:bg-slate-800 shadow-lg transition-all"
                 >
                    <Plus size={16} /> 新建物料
                 </button>
              </div>
           </div>

           {/* Table */}
           <div className="flex-1 overflow-auto">
              <table className="w-full text-sm text-left">
                 <thead className="bg-slate-50 text-slate-500 font-bold border-b border-slate-100 sticky top-0 z-10">
                    <tr>
                       <th className="px-6 py-4 w-12"><input type="checkbox" className="rounded text-blue-600" /></th>
                       <th className="px-6 py-4">物料编码</th>
                       <th className="px-6 py-4">物料名称 / 规格</th>
                       <th className="px-6 py-4">所属目录</th>
                       <th className="px-6 py-4">物料类型</th>
                       <th className="px-6 py-4 text-center">单位</th>
                       <th className="px-6 py-4 text-right">参考单价</th>
                       <th className="px-6 py-4 text-center">状态</th>
                       <th className="px-6 py-4 text-center">操作</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                    {filteredMaterials.map((m) => (
                       <tr key={m.id} className="hover:bg-slate-50 transition-colors group">
                          <td className="px-6 py-4"><input type="checkbox" className="rounded text-blue-600" /></td>
                          <td className="px-6 py-4 font-mono text-slate-500">{m.code}</td>
                          <td className="px-6 py-4">
                             <p className="font-bold text-slate-900">{m.name}</p>
                             <p className="text-xs text-slate-400">{m.spec}</p>
                          </td>
                          <td className="px-6 py-4">
                             <span className="bg-slate-100 px-2 py-1 rounded text-xs text-slate-600 font-medium">{m.category}</span>
                          </td>
                          <td className="px-6 py-4">
                             <span className={`inline-flex items-center gap-1 text-xs font-bold ${
                                m.type === '固定资产' ? 'text-purple-600' : 
                                m.type === '原料' ? 'text-blue-600' : 'text-slate-600'
                             }`}>
                                {m.type}
                             </span>
                          </td>
                          <td className="px-6 py-4 text-center text-slate-500">{m.unit}</td>
                          <td className="px-6 py-4 text-right font-mono font-bold text-slate-900">¥{m.price.toLocaleString()}</td>
                          <td className="px-6 py-4 text-center">
                             <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-bold ${m.status === 'active' ? 'bg-green-50 text-green-700' : 'bg-slate-100 text-slate-500'}`}>
                                <span className={`w-1.5 h-1.5 rounded-full ${m.status === 'active' ? 'bg-green-500' : 'bg-slate-400'}`}></span>
                                {m.status === 'active' ? '启用' : '停用'}
                             </span>
                          </td>
                          <td className="px-6 py-4 text-center">
                             <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <button title="编辑" className="p-1.5 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition-colors">
                                   <Edit3 size={14} />
                                </button>
                                <button title="停用/删除" className="p-1.5 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg transition-colors">
                                   <Trash2 size={14} />
                                </button>
                             </div>
                          </td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>

           {/* Pagination */}
           <div className="p-4 border-t border-slate-100 flex justify-between items-center text-xs text-slate-500">
              <span>显示 1 到 {filteredMaterials.length} 条，共 {filteredMaterials.length} 条</span>
              <div className="flex gap-2">
                 <button className="px-3 py-1 bg-white border border-slate-200 rounded hover:bg-slate-50 disabled:opacity-50" disabled>上一页</button>
                 <button className="px-3 py-1 bg-white border border-slate-200 rounded hover:bg-slate-50 disabled:opacity-50" disabled>下一页</button>
              </div>
           </div>
        </div>
      </div>
    );
  };

  // ... Reuse existing code for Org / Material views or simplify for brevity if not focus ...
  if (initialTab === 'workflow') return renderWorkflowView();
  if (initialTab === 'org') return renderOrgManagement();
  if (initialTab === 'permission') return renderPermissionManagement();
  if (initialTab === 'material') return renderMaterialManagement();

  return (
    <div className="flex flex-col items-center justify-center py-40 text-slate-400 bg-white rounded-3xl border border-dashed border-slate-200">
        <Settings size={64} className="mb-4 text-slate-200" />
        <p className="text-lg font-bold text-slate-900">其他系统管理模块</p>
        <p className="text-sm mt-1">请点击“流程设置”或“组织架构”体验新版功能</p>
    </div>
  );
};

