  id: string;
  name: string;
  count?: number;
  expanded?: boolean;
  children?: DeptNode[];
}

interface Member {
  id: string;
  name: string;
  avatar?: string;
  role: string;
  jobNo: string;
  phone: string;
  email: string;
  status: 'active' | 'inactive';
