  id: string;
  name: string;
  description: string;
  isSystem: boolean;
  memberCount: number;
}

// --- Types for Material ---
interface MaterialCategory {
  id: string;
  name: string;
  count: number;
  expanded?: boolean;
  children?: MaterialCategory[];
}

interface MaterialItem {
  id: string;
  code: string;
  name: string;
  spec: string;
  category: string; // Directory
  type: string; // Material Type (e.g., Raw Material, Asset)
  unit: string;
