                    {currentCatName || '全部物料'} 
                    <span className="text-sm font-medium text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">
                       {filteredMaterials.length} 条
                    </span>
                 </h2>
                 <p className="text-xs text-slate-500 mt-1">物料主数据管理中心</p>
              </div>
              <div className="flex gap-3">
                 <div className="relative">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="搜索物料编码、名称或规格..." 
                      value={materialSearch}
                      onChange={(e) => setMaterialSearch(e.target.value)}
                      className="pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 w-64" 
                    />
                 </div>
                 <button className="flex items-center gap-2 px-4 py-2.5 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50 transition-all">
                    <UploadCloud size={16} /> 导入
                 </button>
                 <button 
                   onClick={() => setIsCreatingMaterial(true)}
