                            </button>
                         ))}
                      </div>
                   </div>

                   {/* Center: Canvas */}
                   <div className="flex-1 bg-white rounded-xl shadow-sm border border-slate-200 p-8 overflow-y-auto">
                      <div className="max-w-xl mx-auto space-y-4">
                         {formFields.map((field) => (
                            <div 
                              key={field.id}
