                              className={`group relative p-4 rounded-xl border-2 transition-all cursor-pointer ${activeFieldId === field.id ? 'border-blue-500 bg-blue-50/20' : 'border-transparent hover:border-slate-200 bg-slate-50'}`}
                            >
