                               </div>
                            )}

                            {selectedNode.type === 'condition' && (
                               <div>
                                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">条件规则</label>
                                  <div className="p-3 bg-slate-50 rounded-lg border border-slate-200 text-sm text-slate-500 text-center">
                                     <p>点击配置筛选条件</p>
                                     <button className="mt-2 text-blue-600 font-bold hover:underline">设置条件</button>
                                  </div>
                                  <div className="mt-4">
                                     <label className="block text-xs font-bold text-slate-500 uppercase mb-2">显示内容</label>
                                     <input 
                                       type="text" 
                                       value={selectedNode.content} 
                                       onChange={(e) => handleUpdateNode(selectedNode.id, { content: e.target.value })}
                                       className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-sm outline-none focus:border-blue-500" 
                                     />
                                  </div>
                               </div>
                            )}
                         </div>
                      ) : (
                         <div className="p-10 text-center text-slate-400">
                            请选择节点
                         </div>
                      )}
                   </div>
                </>
             )}
          </div>
       </div>
    );
  };

  // Main Render
  if (initialTab === 'workflow') return renderWorkflowView();
  if (initialTab === 'org') return renderOrgManagement();
  if (initialTab === 'permission') return renderPermissionManagement();
  if (initialTab === 'material') return renderMaterialManagement();

  return (
    <div className="flex flex-col items-center justify-center py-40 text-slate-400 bg-white rounded-3xl border border-dashed border-slate-200">
        <Settings size={64} className="mb-4 text-slate-200" />
        <p className="text-lg font-bold text-slate-900">其他系统管理模块</p>
        <p className="text-sm mt-1">请点击“流程设置”或“组织架构”体验新版功能</p>
    </div>
  );
};

