  const handleEditWorkflow = (workflow: WorkflowDef) => {
    setEditingWorkflow(workflow);
    setFormFields(workflow.formFields);
    setFlowData(workflow.flowData);
    setEditorMode('edit');
    setEditorTab('forms');
    setWorkflowView('editor');
  };

