          if (p.budget > 50000 && p.solicitationMethod === '邀请' && p.items.length < 3) {
             issues.push('邀请招标供应商数量可能不足，建议增加候选名单');
             score -= 10;
          }
          if (issues.length === 0) issues.push('暂未发现明显合规风险');

          return {
            ...p,
            aiRiskAnalysis: {
              score,
              issues,
              suggestion: score > 80 ? '方案整体合规，建议推进。' : '建议修改采购方式或增加内控审批流程。'
            }
          };
        }
        return p;
      }));
